WITH catalog_daily AS ( SELECT d.d_date AS sales_date, SUM(cs.cs_net_paid_inc_tax) AS catalog_net_paid, SUM(cs.cs_net_profit) AS catalog_profit FROM catalog_sales cs JOIN date_dim d ON cs.cs_sold_date_sk = d.d_date_sk GROUP BY d.d_date ), web_daily AS ( SELECT d.d_date AS sales_date, SUM(ws.ws_net_paid_inc_tax) AS web_net_paid, SUM(ws.ws_net_profit) AS web_profit FROM web_sales ws JOIN date_dim d ON ws.ws_sold_date_sk = d.d_date_sk GROUP BY d.d_date ) SELECT COALESCE(cd.sales_date, wd.sales_date) AS sales_date, cd.catalog_net_paid, wd.web_net_paid, wd.web_net_paid - cd.catalog_net_paid AS net_paid_diff, CASE WHEN cd.catalog_net_paid = 0 THEN NULL ELSE wd.web_net_paid / cd.catalog_net_paid END AS web_to_catalog_ratio, CASE WHEN cd.catalog_net_paid = 0 THEN 'Undefined' WHEN wd.web_net_paid > cd.catalog_net_paid * 1.10 THEN 'Web > Catalog +10%' ELSE 'Normal' END AS sales_flag, RANK() OVER (ORDER BY (COALESCE(cd.catalog_net_paid,0) + COALESCE(wd.web_net_paid,0)) DESC) AS total_sales_rank FROM catalog_daily cd FULL OUTER JOIN web_daily wd ON cd.sales_date = wd.sales_date ORDER BY total_sales_rank LIMIT 100
